/*
 * MST_$MAP_INITIAL_AREA - hand a parent's VM area to a new address space
 * and map it there
 *
 * Original address: 0x00E42E9E (SAU2 map: MST_$MAP_INITIAL_AREA at E42E9E)
 * Size: 182 bytes (0x00E42E9E .. 0x00E42F53)
 * Generated by: Claude Opus 5.5
 *
 * Callers: PROC2_$CREATE (0x00E7282E), proc2_$complete_vfork (0x00E7376E).
 * Frame (link.w A6,-0x10; D2-D4/A2-A3/A5 saved; A5 = 0xE7CF0C, unused):
 *   (0x08,A6) code_desc  longword, the VA to map at (D2)
 *   (0x0C)    asid       word
 *   (0x0E)    parent_uid the area's UID (A2)
 *   (0x12)    map_param  longword, the area's new virtual size and the
 *                        mapped length
 *   (0x16)    area_kind  word, mst_$alloc_segs' area id
 *   (0x18)    touch      Domain boolean (D4b)
 *   (0x1A)    status     (A3)
 *   locals: (-0x04) map_info, (-0x0C) the unmap status, (-0x0E) the
 *   segment of code_desc.
 *
 * Blocks:
 *   0x00E42EB8-0x00E42ECC  the UID must be an ANON area's (high longword ==
 *                          ANON_$UID's), else status_$mst_uid_not_vm_area
 *   0x00E42ECE-0x00E42EF6  AREA_$TRANSFER(&uid.low, asid, code_desc >> 15,
 *                          map_param); its word result (D3w) is the area's
 *                          previous segment
 *   0x00E42EF8-0x00E42F20  mst_$alloc_segs at code_desc in `asid` with
 *                          MST_$TOUCH_COUNT
 *   0x00E42F24-0x00E42F46  touch: unmap the one 32 KB segment at the
 *                          previous segment in the CURRENT address space
 *
 * Quirk reproduced: the mst_$alloc_segs status is not tested before the
 * unmap (0x00E42F24 tests only D4b).
 */

#include "mst/mst_internal.h"
#include "anon/anon.h"

/* `lsr.l #0x8` + `lsr.l #0x7` 0x00E42ED0 / `lsl.l` pair 0x00E42F3C */
#define MST_INITIAL_SEG_SHIFT   15
/* `move.l #0x8000,-(SP)` 0x00E42F32: one segment */
#define MST_INITIAL_SEG_SIZE    0x8000u
/* `clr.w -(SP)` 0x00E42F44: MST_$UNMAP_PRIVI mode */
#define MST_INITIAL_UNMAP_MODE  0

void MST_$MAP_INITIAL_AREA(uint32_t code_desc, uint16_t asid, uid_t *parent_uid,
                           uint32_t map_param, int16_t area_kind, boolean touch,
                           status_$t *status)
{
    uint32_t map_info;          /* (-0x04,A6) */
    status_$t unmap_status;     /* (-0x0C,A6) */
    uint16_t seg;               /* (-0x0E,A6) */
    uint16_t old_seg;           /* D3w */

    /* 0x00E42EB8-0x00E42ECC */
    if (parent_uid->high != ANON_$UID.high) {
        *status = status_$mst_uid_not_vm_area;
        return;
    }

    /* 0x00E42ECE-0x00E42EF6 */
    seg = (uint16_t)(code_desc >> MST_INITIAL_SEG_SHIFT);
    old_seg = (uint16_t)AREA_$TRANSFER(&parent_uid->low, (int16_t)asid,
                                       (int16_t)seg, map_param, status);
    if (*status != status_$ok) {
        return;
    }

    /* 0x00E42EF8-0x00E42F20 */
    mst_$alloc_segs(code_desc, parent_uid, 0, map_param, 0, (int16_t)asid,
                    (uint16_t)area_kind, MST_$TOUCH_COUNT, 0, false, &map_info,
                    status);

    /* 0x00E42F24-0x00E42F46 */
    if (touch < 0) {
        MST_$UNMAP_PRIVI(MST_INITIAL_UNMAP_MODE, parent_uid,
                         (uint32_t)old_seg << MST_INITIAL_SEG_SHIFT,
                         MST_INITIAL_SEG_SIZE, PROC1_$AS_ID, &unmap_status);
    }
}
